export interface TokenBucketPolicy {
  burst: number;
  ratePerSec: number;
}

interface State {
  tokens: number;
  updatedAt: number;
}

export class DriverPingLimiter {
  private readonly state = new Map<string, State>();

  constructor(
    private readonly policy: TokenBucketPolicy,
    private readonly clock: () => number = () => performance.now(),
  ) {}

  allow(driverId: string): { allowed: boolean; waitMs: number } {
    const t = this.clock();
    const prev = this.state.get(driverId);
    const elapsedSec = prev ? Math.max(0, (t - prev.updatedAt) / 1000) : 0;
    const available = prev
      ? Math.min(this.policy.burst, prev.tokens + elapsedSec * this.policy.ratePerSec)
      : this.policy.burst;

    if (available >= 1) {
      this.state.set(driverId, { tokens: available - 1, updatedAt: t });
      return { allowed: true, waitMs: 0 };
    }

    this.state.set(driverId, { tokens: available, updatedAt: t });
    const waitMs = ((1 - available) / this.policy.ratePerSec) * 1000;
    return { allowed: false, waitMs: Math.ceil(waitMs) };
  }

  forget(driverId: string) {
    this.state.delete(driverId);
  }

  size() {
    return this.state.size;
  }
}

import { DriverPingLimiter } from "./driverPingLimiter";

export interface LocationPing {
  driverId: string;
  lat: number;
  lng: number;
  recordedAt: number;
}

export interface DispatchIndex {
  upsertDriverPosition(ping: LocationPing): Promise<void>;
}

export interface Metrics {
  increment(name: string, tags?: Record<string, string>): void;
}

export class LocationIngest {
  private readonly limiter = new DriverPingLimiter({ burst: 3, ratePerSec: 1 });

  constructor(
    private readonly index: DispatchIndex,
    private readonly metrics: Metrics,
  ) {}

  async onPing(ping: LocationPing): Promise<{ status: number; retryAfterMs?: number }> {
    if (
      !Number.isFinite(ping.lat) || Math.abs(ping.lat) > 90 ||
      !Number.isFinite(ping.lng) || Math.abs(ping.lng) > 180
    ) {
      this.metrics.increment("location.ping.invalid");
      return { status: 400 };
    }

    const { allowed, waitMs } = this.limiter.allow(ping.driverId);
    if (!allowed) {
      this.metrics.increment("location.ping.throttled");
      return { status: 429, retryAfterMs: waitMs };
    }

    await this.index.upsertDriverPosition(ping);
    this.metrics.increment("location.ping.accepted");
    return { status: 202 };
  }

  onDriverOffline(driverId: string) {
    this.limiter.forget(driverId);
  }
}
